  <div class="news-view">
    <!-- 页面头部区域 -->
    <section class="page-header">
      <div class="header-content">
        <h1 class="page-title">非遗资讯</h1>
        <p class="page-subtitle">第一时间获取湖北非遗保护工作的最新动态、活动通知和传承故事</p>
      </div>
    </section>

    <div class="news-container">
      <!-- 主内容区域 -->
      <main class="main-content">
        <!-- 筛选工具栏：分类筛选 + 视图切换 -->
        <div class="filter-bar">
          <div class="category-filters">
            <button
              v-for="cat in categories"
              :key="cat.value"
              class="filter-btn"
              :class="{ active: currentCategory === cat.value }"
              @click="setCategory(cat.value)"
            >
              {{ cat.label }}
            </button>
          </div>
          <div class="view-toggle">
            <button
              class="toggle-btn"
              :class="{ active: viewMode === 'list' }"
              @click="viewMode = 'list'"
              title="列表视图"
            >
              <svg width="18" height="18" viewBox="0 0 18 18" fill="none">
                <path d="M2 4h14M2 9h14M2 14h14" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" />
              </svg>
            </button>
            <button
              class="toggle-btn"
              :class="{ active: viewMode === 'grid' }"
              @click="viewMode = 'grid'"
              title="卡片视图"
            >
              <svg width="18" height="18" viewBox="0 0 18 18" fill="none">
                <rect x="2" y="2" width="5" height="5" rx="1" stroke="currentColor" stroke-width="1.5" />
                <rect x="11" y="2" width="5" height="5" rx="1" stroke="currentColor" stroke-width="1.5" />
                <rect x="2" y="11" width="5" height="5" rx="1" stroke="currentColor" stroke-width="1.5" />
                <rect x="11" y="11" width="5" height="5" rx="1" stroke="currentColor" stroke-width="1.5" />
              </svg>
            </button>
          </div>
        </div>

        <!-- 标签云 -->
        <div class="tag-cloud">
          <span class="tag-label">热门标签：</span>
          <span
            v-for="tag in hotTags"
            :key="tag"
            class="tag-item"
            :class="{ active: selectedTag === tag }"
            @click="toggleTag(tag)"
          >
            {{ tag }}
          </span>
        </div>

        <!-- 加载状态 -->
        <LoadingSpinner v-if="loading && !newsList.length" />

        <!-- 空状态 -->
        <EmptyState
          v-else-if="!filteredNews.length"
          title="暂无相关资讯"
          description="当前分类下没有资讯内容，试试其他分类吧"
        />

        <!-- 资讯列表 - 列表视图 -->
        <TransitionGroup
          v-else-if="viewMode === 'list'"
          name="list"
          tag="div"
          class="news-list"
        >
          <NewsCard
            v-for="item in paginatedNews"
            :key="item.id"
            :news="item"
            layout="list"
            @click="goToDetail(item.id)"
          />
        </TransitionGroup>

        <!-- 资讯列表 - 卡片视图 -->
        <TransitionGroup
          v-else
          name="grid"
          tag="div"
          class="news-grid"
        >
          <NewsCard
            v-for="item in paginatedNews"
            :key="item.id"
            :news="item"
            layout="grid"
            @click="goToDetail(item.id)"
          />
        </TransitionGroup>

        <!-- 分页组件 -->
        <div v-if="totalPages > 1" class="pagination">
          <button
            class="page-btn"
            :disabled="currentPage === 1"
            @click="currentPage--"
          >
            上一页
          </button>
          <span
            v-for="page in visiblePages"
            :key="page"
            class="page-number"
            :class="{ active: currentPage === page }"
            @click="currentPage = page"
          >
            {{ page }}
          </span>
          <button
            class="page-btn"
            :disabled="currentPage === totalPages"
            @click="currentPage++"
          >
            下一页
          </button>
        </div>
      </main>

      <!-- 右侧边栏 - 桌面端显示 -->
      <aside v-if="!isMobile" class="sidebar">
        <!-- 热门标签 -->
        <div class="sidebar-section">
          <h3 class="sidebar-title">热门标签</h3>
          <div class="sidebar-tags">
            <span
              v-for="tag in sidebarTags"
              :key="tag.name"
              class="sidebar-tag"
              :style="{ fontSize: tag.size + 'px' }"
              @click="toggleTag(tag.name)"
            >
              {{ tag.name }}
            </span>
          </div>
        </div>

