        <div class="sidebar-section">
          <h3 class="sidebar-title">推荐阅读</h3>
          <div class="recommended-list">
            <div
              v-for="item in recommendedNews"
              :key="item.id"
              class="recommended-item"
              @click="goToDetail(item.id)"
            >
              <img :src="item.cover" :alt="item.title" class="recommended-img" />
              <div class="recommended-info">
                <p class="recommended-title">{{ item.title }}</p>
                <span class="recommended-date">{{ formatDate(item.createdAt) }}</span>
              </div>
            </div>
          </div>
        </div>
