</template>

<script setup>
/**
 * NewsView.vue - 非遗资讯页面
 *
 * 功能说明：
 * - 展示湖北非遗保护工作的最新动态、活动通知和传承故事
 * - 支持分类筛选（保护动态/传承人故事/展览活动/政策法规/学术研究）
 * - 支持标签云筛选
 * - 支持列表视图和卡片视图切换
 * - 右侧边栏展示热门标签和推荐阅读
 * - 完整的分页、加载状态和空状态处理
 */
import { ref, computed, onMounted, watch } from 'vue'
import { useStore } from 'vuex'
import { useRouter } from 'vue-router'
import NewsCard from '@/components/NewsCard.vue'
import LoadingSpinner from '@/components/LoadingSpinner.vue'
import EmptyState from '@/components/EmptyState.vue'

// 获取 Vuex store 和 router 实例
const store = useStore()
const router = useRouter()

// ==================== 响应式状态 ====================

/** 当前选中的分类 */
const currentCategory = ref('all')
/** 当前选中的标签 */
const selectedTag = ref('')
/** 视图模式：list 列表视图 / grid 卡片视图 */
const viewMode = ref('list')
/** 当前页码 */
const currentPage = ref(1)
/** 每页显示数量 */
const pageSize = ref(10)
/** 是否移动端 */
const isMobile = ref(window.innerWidth < 768)

// ==================== 分类配置 ====================

/** 新闻分类选项 */
const categories = [
  { label: '全部', value: 'all' },
  { label: '保护动态', value: '保护动态' },
  { label: '传承人故事', value: '传承人故事' },
  { label: '展览活动', value: '展览活动' },
  { label: '政策法规', value: '政策法规' },
  { label: '学术研究', value: '学术研究' }
]

// ==================== 计算属性 ====================

/** 从 Vuex store 获取加载状态 */
const loading = computed(() => store.state.loading)

/** 从 Vuex store 获取新闻列表 */
const newsList = computed(() => store.state.news || [])

/** 根据分类和标签筛选后的新闻列表 */
const filteredNews = computed(() => {
  let result = newsList.value
  // 按分类筛选
  if (currentCategory.value !== 'all') {
    result = result.filter(item => item.category === currentCategory.value)
  }
  // 按标签筛选
  if (selectedTag.value) {
    result = result.filter(item => item.tags && item.tags.includes(selectedTag.value))
  }
  return result
})

/** 分页后的新闻列表 */
const paginatedNews = computed(() => {
  const start = (currentPage.value - 1) * pageSize.value
  const end = start + pageSize.value
  return filteredNews.value.slice(start, end)
})

/** 总页数 */
const totalPages = computed(() => Math.ceil(filteredNews.value.length / pageSize.value))

/** 可见的页码范围 */
const visiblePages = computed(() => {
  const pages = []
  const max = totalPages.value
  const current = currentPage.value
  let start = Math.max(1, current - 2)
  let end = Math.min(max, current + 2)
  if (end - start < 4) {
    if (start === 1) end = Math.min(max, start + 4)
    else if (end === max) start = Math.max(1, end - 4)
  }
  for (let i = start; i <= end; i++) pages.push(i)
  return pages
})

/** 热门标签列表 */
const hotTags = computed(() => {
  const tagSet = new Set()
  newsList.value.forEach(item => {
    if (item.tags) item.tags.forEach(tag => tagSet.add(tag))
  })
  return Array.from(tagSet).slice(0, 12)
})

/** 侧边栏标签（带字体大小权重） */
const sidebarTags = computed(() => {
  const tagCount = {}
  newsList.value.forEach(item => {
    if (item.tags) {
      item.tags.forEach(tag => {
        tagCount[tag] = (tagCount[tag] || 0) + 1
      })
    }
  })
  return Object.entries(tagCount)
    .map(([name, count]) => ({
      name,
      size: Math.max(12, Math.min(20, 12 + count * 2))
    }))
    .sort((a, b) => b.size - a.size)
    .slice(0, 20)
})

/** 推荐阅读（浏览量最高的5篇） */
const recommendedNews = computed(() => {
  return [...newsList.value]
    .sort((a, b) => (b.views || 0) - (a.views || 0))
    .slice(0, 5)
})

// ==================== 方法 ====================

/**
 * 设置当前分类，并重置页码
 * @param {string} value - 分类值
 */
const setCategory = (value) => {
  currentCategory.value = value
  currentPage.value = 1
}

/**
 * 切换标签筛选
 * @param {string} tag - 标签名称
 */
const toggleTag = (tag) => {
  selectedTag.value = selectedTag.value === tag ? '' : tag
  currentPage.value = 1
}

/**
 * 跳转到新闻详情页
 * @param {string} id - 新闻ID
 */
const goToDetail = (id) => {
  router.push(`/news/${id}`)
}

/**
 * 格式化日期显示
 * @param {string} dateStr - ISO日期字符串
 * @returns {string} 格式化后的日期
 */
const formatDate = (dateStr) => {
  if (!dateStr) return ''
  const date = new Date(dateStr)
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
}

/**
 * 处理窗口大小变化，更新移动端状态
 */
const handleResize = () => {
  isMobile.value = window.innerWidth < 768
}

// ==================== 生命周期 ====================

onMounted(async () => {
  // 添加窗口大小监听
  window.addEventListener('resize', handleResize)
  // 获取新闻数据
  try {
    await store.dispatch('fetchNews')
  } catch (err) {
    console.error('获取新闻列表失败:', err)
  }
})
</script>

